#!/usr/bin/env node
/**
 * Attribute the shell (entry) JavaScript to the modules that produced it.
 *
 * The budget script reports one number for the entry plus its static imports.
 * When that number jumps, the next question is which module grew. Vite is built
 * here with `--sourcemap`, so every generated byte has a source index; walk the
 * mappings, give each segment the generated text up to the next segment, and
 * group the result by package and file.
 *
 * Sizes are per-module gzip of that module's generated text, summed. Summing
 * gzip sizes overstates the total (each stream pays its own header and cannot
 * share the dictionary), so read the table as a share of the whole, not as
 * megabytes that add up to the reported shell size. Raw bytes are printed too.
 *
 * Usage:
 *   node scripts/shell-attribution.mjs [distDir] [--top N] [--json]
 * Default distDir is apps/web/dist. Requires a build made with --sourcemap.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { gzipSync } from 'node:zlib';

const root = new URL('..', import.meta.url).pathname;
const args = process.argv.slice(2);
const json = args.includes('--json');
const topIndex = args.indexOf('--top');
const top = topIndex === -1 ? 25 : Number(args[topIndex + 1]);
const distArgument = args.filter(
  (argument, index) => !argument.startsWith('--') && index !== topIndex + 1,
)[0];
const dist = distArgument ? join(root, distArgument) : join(root, 'apps/web/dist');

const manifestPath = join(dist, '.vite/manifest.json');
if (!existsSync(manifestPath)) {
  console.error(`attribution: no manifest at ${manifestPath}; build first`);
  process.exit(1);
}

const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const entry = manifest['index.html'];
if (!entry) {
  console.error('attribution: index.html is missing from the manifest');
  process.exit(1);
}

function shellKeys(key, seen = new Set()) {
  if (seen.has(key)) return [];
  seen.add(key);
  const chunk = manifest[key];
  if (!chunk) return [];
  return [key, ...(chunk.imports ?? []).flatMap((imported) => shellKeys(imported, seen))];
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const VALUES = new Map([...BASE64].map((character, index) => [character, index]));

/** Decodes one line of `mappings` into [generatedColumn, sourceIndex] pairs. */
function decodeLine(line, state) {
  const segments = [];
  let column = 0;
  if (line === '') return segments;
  for (const segment of line.split(',')) {
    if (segment === '') continue;
    const fields = [];
    let value = 0;
    let shift = 0;
    for (const character of segment) {
      const digit = VALUES.get(character);
      if (digit === undefined) throw new Error(`bad VLQ character ${character}`);
      value += (digit & 31) << shift;
      if (digit & 32) {
        shift += 5;
      } else {
        fields.push(value & 1 ? -(value >>> 1) : value >>> 1);
        value = 0;
        shift = 0;
      }
    }
    column += fields[0] ?? 0;
    if (fields.length >= 4) {
      state.source += fields[1];
      state.sourceLine += fields[2];
      state.sourceColumn += fields[3];
      segments.push([column, state.source]);
    }
  }
  return segments;
}

/** Splits a minified chunk into per-source pieces using its sourcemap. */
function attributeChunk(code, map) {
  const sources = map.sources;
  const lineStarts = [0];
  for (let index = 0; index < code.length; index += 1) {
    if (code[index] === '\n') lineStarts.push(index + 1);
  }

  const state = { source: 0, sourceLine: 0, sourceColumn: 0 };
  const segments = [];
  for (const [lineIndex, line] of map.mappings.split(';').entries()) {
    const lineStart = lineStarts[lineIndex];
    if (lineStart === undefined) break;
    for (const [column, source] of decodeLine(line, state)) {
      segments.push({ offset: lineStart + column, source });
    }
  }

  const pieces = new Map();
  for (const [index, segment] of segments.entries()) {
    const end = segments[index + 1]?.offset ?? code.length;
    if (end <= segment.offset) continue;
    const name = sources[segment.source];
    if (!name) continue;
    const text = code.slice(segment.offset, end);
    pieces.set(name, (pieces.get(name) ?? '') + text);
  }
  return pieces;
}

/** Buckets a source path by the package that owns it. */
function bucketOf(path) {
  const normalised = path.replaceAll('\\', '/');
  const nodeModules = normalised.split('node_modules/').pop();
  if (normalised.includes('node_modules/')) {
    const parts = nodeModules.split('/');
    const name = parts[0]?.startsWith('@') ? `${parts[0]}/${parts[1]}` : parts[0];
    return name ?? 'node_modules';
  }
  if (normalised.includes('packages/tool-core/')) return '@omnitool/tool-core';
  if (normalised.includes('packages/tools-registry/')) return '@omnitool/tools-registry';
  if (normalised.includes('packages/ui/')) return '@omnitool/ui';
  const src = normalised.split('/src/').pop();
  if (src && src !== normalised) return `src/${src.split('/')[0]}`;
  return 'other';
}

const files = new Map();
const buckets = new Map();
let totalRaw = 0;
let totalGzip = 0;

for (const key of shellKeys('index.html')) {
  const chunk = manifest[key];
  if (!chunk?.file?.endsWith('.js')) continue;
  const chunkPath = join(dist, chunk.file);
  const mapPath = `${chunkPath}.map`;
  const code = readFileSync(chunkPath, 'utf8');
  totalRaw += Buffer.byteLength(code);
  totalGzip += gzipSync(code).length;
  if (!existsSync(mapPath)) {
    // The 1 kB rolldown runtime chunk is emitted without a map; keep its bytes
    // in the totals under a name that says so rather than dropping them.
    const name = `<unmapped ${relative(dist, chunkPath)}>`;
    const bytes = Buffer.byteLength(code);
    const gzip = gzipSync(code).length;
    files.set(name, { bytes, gzip });
    buckets.set('runtime', { bytes, gzip });
    continue;
  }
  const pieces = attributeChunk(code, JSON.parse(readFileSync(mapPath, 'utf8')));
  for (const [path, text] of pieces) {
    const bytes = Buffer.byteLength(text);
    const gzip = gzipSync(text).length;
    const existing = files.get(path) ?? { bytes: 0, gzip: 0 };
    files.set(path, { bytes: existing.bytes + bytes, gzip: existing.gzip + gzip });
    const bucket = bucketOf(path);
    const bucketTotal = buckets.get(bucket) ?? { bytes: 0, gzip: 0 };
    buckets.set(bucket, { bytes: bucketTotal.bytes + bytes, gzip: bucketTotal.gzip + gzip });
  }
}

const rows = [...files.entries()]
  .map(([path, size]) => ({ path, ...size }))
  .sort((a, b) => b.gzip - a.gzip);
const bucketRows = [...buckets.entries()]
  .map(([bucket, size]) => ({ bucket, ...size }))
  .sort((a, b) => b.gzip - a.gzip);

if (json) {
  console.log(JSON.stringify({ totalRaw, totalGzip, buckets: bucketRows, files: rows }, null, 2));
} else {
  const kb = (bytes) => `${(bytes / 1024).toFixed(1)} kB`;
  console.log(
    `Shell chunks: ${shellKeys('index.html')
      .map((key) => manifest[key].file)
      .join(', ')}`,
  );
  console.log(`Shell total: ${kb(totalRaw)} raw, ${kb(totalGzip)} gzip`);
  console.log('\nBy package (summed per-module gzip is an upper bound):');
  for (const row of bucketRows.slice(0, top)) {
    const share = ((row.gzip / totalGzip) * 100).toFixed(1);
    console.log(`  ${row.bucket.padEnd(28)} ${kb(row.gzip).padStart(10)}  ${share.padStart(5)}%`);
  }
  console.log('\nLargest modules:');
  for (const row of rows.slice(0, top)) {
    console.log(
      `  ${kb(row.gzip).padStart(10)}  ${((row.gzip / totalGzip) * 100).toFixed(1).padStart(5)}%  ${row.path}`,
    );
  }
}
